      thirdPartyHeading: "\u0645\u0644\u0641\u0627\u062a \u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0627\u0631\u062a\u0628\u0627\u0637 \u0645\u0646 \u062c\u0647\u0627\u062a \u062e\u0627\u0631\u062c\u064a\u0629",
      thirdPartyBody: "\u0625\u0630\u0627 \u0633\u062c\u0651\u0644\u062a \u0627\u0644\u062f\u062e\u0648\u0644\u060c \u0641\u0625\u0646\u0643 \u062a\u0645\u0631 \u0639\u0628\u0631 Supabase\u060c \u0645\u0632\u0648\u0651\u062f \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0644\u062f\u064a\u0646\u0627\u060c \u0648\u0645\u0632\u0648\u0651\u062f \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u064a \u062a\u062e\u062a\u0627\u0631\u0647\u060c \u0645\u062b\u0644 Google. \u0642\u062f \u064a\u0636\u0639 \u0647\u0624\u0644\u0627\u0621 \u0645\u0644\u0641\u0627\u062a \u062a\u0639\u0631\u064a\u0641 \u0627\u0631\u062a\u0628\u0627\u0637 \u0639\u0644\u0649 \u0646\u0637\u0627\u0642\u0627\u062a\u0647\u0645 \u0627\u0644\u062e\u0627\u0635\u0629 \u0623\u062b\u0646\u0627\u0621 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644\u060c \u0648\u0641\u0642 \u0633\u064a\u0627\u0633\u0627\u062a\u0647\u0645 \u0627\u0644\u062e\u0627\u0635\u0629. \u0644\u0627 \u0646\u0633\u062a\u062e\u062f\u0645 \u062a\u0644\u0643 \u0627\u0644\u0645\u0644\u0641\u0627\u062a \u0644\u0644\u062a\u062a\u0628\u0639.",
      managingHeading: "\u0625\u062f\u0627\u0631\u0629 \u0645\u0644\u0641\u0627\u062a \u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0627\u0631\u062a\u0628\u0627\u0637 \u0648\u0627\u0644\u062a\u062e\u0632\u064a\u0646",
      managingBody: "\u064a\u0645\u0643\u0646\u0643 \u0645\u0633\u062d \u0645\u0644\u0641\u0627\u062a \u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0627\u0631\u062a\u0628\u0627\u0637 \u0648\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0648\u0642\u0639 \u0623\u0648 \u062d\u0638\u0631\u0647\u0627 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0645\u062a\u0635\u0641\u062d\u0643 \u0641\u064a \u0623\u064a \u0648\u0642\u062a. \u064a\u0624\u062f\u064a \u0645\u0633\u062d\u0647\u0627 \u0625\u0644\u0649 \u062a\u0633\u062c\u064a\u0644 \u062e\u0631\u0648\u062c\u0643 \u0648\u0625\u0639\u0627\u062f\u0629 \u0636\u0628\u0637 \u062a\u0641\u0636\u064a\u0644\u0627\u062a\u0643. \u0644\u0623\u064a \u0623\u0633\u0626\u0644\u0629\u060c \u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627 \u0639\u0644\u0649 {email}.",
      manageButton: "\u0625\u062f\u0627\u0631\u0629 \u062a\u0641\u0636\u064a\u0644\u0627\u062a \u0645\u0644\u0641\u0627\u062a \u062a\u0639\u0631\u064a\u0641 \u0627\u0644\u0627\u0631\u062a\u0628\u0627\u0637"
